INSERT INTO public.places (name,category,place_type,city,latitude,longitude,slug,short_description,long_description,source_url,external_source,verified,trust_score,is_active,content_review_status,tags,updated_at,verified_at)
SELECT v.name,'Doğa','Dağ',v.city,v.lat,v.lon,v.slug,v.short_desc,v.long_desc,v.url,'İl Kültür ve Turizm Müdürlüğü',true,90,true,'source_backed',v.tags::jsonb,now(),now()
FROM (VALUES
('Tahtalı Dağı','Antalya',36.5580,30.1250,'tahtali-dagi-antalya','Beydağları üzerinde, Akdeniz kıyısı ile yüksek dağ manzarasını bir araya getiren belirgin zirve.','Antalya İl Kültür ve Turizm Müdürlüğü, Tahtalı Dağı’nı bölgenin önemli dorukları arasında sayar. Zirve yürüyüşü hava, rota ve mevsime göre hazırlık gerektirir.','https://antalya.ktb.gov.tr/TR-68444/dag-ve-doga-yuruyusu.html','["dağ","doğa yürüyüşü","Beydağları","zirve"]'),
('Kızlar Sivrisi','Antalya',36.5700,29.7500,'kizlar-sivrisi-antalya','Beydağları’nın öne çıkan yüksek zirvelerinden; dağcılık ve uzun yürüyüş ilgisi olanlara yönelik.','Antalya İl Kültür ve Turizm Müdürlüğü, Kızlar Sivrisi’ni Beydağları’nın önemli dorukları arasında listeler. Zirve yürüyüşü hazırlık ve uygun hava koşulları gerektirir.','https://antalya.ktb.gov.tr/TR-68444/dag-ve-doga-yuruyusu.html','["dağ","zirve","dağcılık","Beydağları"]'),
('Barla Dağı','Isparta',38.0200,30.7800,'barla-dagi-isparta','Eğirdir Gölü çevresine hâkim manzaralarıyla bilinen, dağ yürüyüşü ilgisi olanlara hitap eden dağ.','Isparta İl Kültür ve Turizm Müdürlüğü, Barla Dağı’nı Eğirdir’in batısında yer alan ve göle hâkim manzaralar sunan bir dağ olarak tanıtır. Rota ve hava koşulları önceden kontrol edilmelidir.','https://isparta.ktb.gov.tr/TR-70982/turizm-amacli-sportif-faaliyetler.html','["dağ","zirve","Eğirdir Gölü","doğa yürüyüşü"]'),
('Demirkazık Zirvesi','Niğde',37.8400,35.1300,'demirkazik-zirvesi-nigde','Aladağlar’ın simge zirvelerinden; yüksek dağ tırmanışlarıyla tanınır.','Niğde İl Kültür ve Turizm Müdürlüğü, Demirkazık’ı Aladağlar’a giriş ve tırmanış rotalarının temel noktalarından biri olarak tanımlar. Bu rota sıradan gezi yürüyüşü değildir; deneyim, ekipman ve koşullara göre rehberlik gerektirebilir.','https://nigde.ktb.gov.tr/TR-273866/aladaglar-milli-parki.html','["Aladağlar","dağcılık","zirve","yüksek dağ"]')
) AS v(name,city,lat,lon,slug,short_desc,long_desc,url,tags)
WHERE NOT EXISTS (SELECT 1 FROM public.places p WHERE p.city=v.city AND lower(trim(p.name))=lower(trim(v.name)));

